12: uintptr_t MemoryReader::FindPattern(const char* pattern, const char* mask, uintptr_t startAddress, size_t searchSize) const
13: {
14:     if (!m_processHandle)
15:         return 0;
16: 
17:     size_t patternLength = strlen(mask);
18:     std::unique_ptr<unsigned char[]> buffer(new unsigned char[searchSize]);
19: 
20:     if (!ReadProcessMemory(m_processHandle, (LPCVOID)startAddress, buffer.get(), searchSize, nullptr))
21:         return 0;
22: 
23:     for (size_t i = 0; i <= searchSize - patternLength; i++)
24:     {
25:         bool match = true;
26:         for (size_t j = 0; j < patternLength; j++)
27:         {
28:             if (mask[j] == 'x' && buffer[i + j] != pattern[j])
29:             {
30:                 match = false;
31:                 break;
32:             }
33:         }
34: 
35:         if (match)
36:             return startAddress + i;
37:     }
38: 
39:     return 0;
40: }

