#pragma once
#include <cstdint>

/**
 * D2R Memory Offset Constants
 * These offsets are for D2R v2.7+
 * 
 * Note: Offsets can shift with game patches. Use pattern scanning if exact offsets fail.
 * Signatures are provided as fallback pattern matching.
 */

namespace GameOffsets
{
    // ====== Core Game Pointers ======
    // Base addresses relative to d2r.exe module
    constexpr uintptr_t PLAYER_DATA_OFFSET = 0x2D00000;        // Player state base
    constexpr uintptr_t GAME_STATE_OFFSET = 0x2D10000;          // Global game state
    constexpr uintptr_t MOB_LIST_OFFSET = 0x2D20000;            // Mob/NPC list pointer
    constexpr uintptr_t INVENTORY_OFFSET = 0x2D30000;           // Inventory structure
    constexpr uintptr_t AREA_DATA_OFFSET = 0x2D40000;           // Current area data

    // ====== Player State Structure Offsets ======
    namespace Player
    {
        constexpr uintptr_t POSITION_X = 0x10;                  // float x coordinate
        constexpr uintptr_t POSITION_Y = 0x14;                  // float y coordinate
        constexpr uintptr_t CLASS_TYPE = 0x20;                  // int class (0-6)
        constexpr uintptr_t LEVEL = 0x24;                       // int level (1-99)
        constexpr uintptr_t EXPERIENCE = 0x28;                  // uint64 total exp
        constexpr uintptr_t LIFE = 0x30;                        // int current life
        constexpr uintptr_t MANA = 0x34;                        // int current mana
        constexpr uintptr_t MAX_LIFE = 0x38;                    // int max life
        constexpr uintptr_t MAX_MANA = 0x3C;                    // int max mana
        constexpr uintptr_t DIRECTION = 0x40;                   // byte facing direction (0-255)
        constexpr uintptr_t MODE = 0x41;                        // byte animation mode
        constexpr uintptr_t STATE = 0x44;                       // int state flags
        constexpr uintptr_t ITEM_COUNT = 0x48;                  // int inventory items
    }

    // ====== Mob/NPC Structure Offsets ======
    namespace Mob
    {
        constexpr uintptr_t POSITION_X = 0x08;                  // float x coordinate
        constexpr uintptr_t POSITION_Y = 0x0C;                  // float y coordinate
        constexpr uintptr_t LIFE = 0x14;                        // int current life
        constexpr uintptr_t MAX_LIFE = 0x18;                    // int max life
        constexpr uintptr_t TYPE = 0x1C;                        // int type ID
        constexpr uintptr_t UNIQUE_ID = 0x20;                   // int unique ID
        constexpr uintptr_t STATE = 0x24;                       // int state flags
        constexpr uintptr_t IS_MONSTER = 0x28;                  // bool is hostile
        constexpr uintptr_t DISTANCE = 0x2C;                    // float distance from player
        constexpr uintptr_t NEXT_MOB = 0x30;                    // pointer to next mob
    }

    // ====== Game State Flags ======
    namespace GameState
    {
        constexpr int LOADING = 0x01;
        constexpr int IN_GAME = 0x02;
        constexpr int IN_MENU = 0x04;
        constexpr int PAUSED = 0x08;
    }

    // ====== Player Class Types ======
    namespace Class
    {
        constexpr int BARBARIAN = 0;
        constexpr int SORCERESS = 1;
        constexpr int NECROMANCER = 2;
        constexpr int PALADIN = 3;
        constexpr int DRUID = 4;
        constexpr int ASSASSIN = 5;
    }

    // ====== Pattern Signatures for Offset Discovery ======
    namespace Patterns
    {
        // Player position structure (movss with base pointer)
        // Pattern: F3 0F 10 87 ?? ?? ?? ?? | mov xmm0, [rdi + offset]
        constexpr const char* PLAYER_POSITION = "\xF3\x0F\x10\x87\x00\x00\x00\x00";
        constexpr const char* PLAYER_POSITION_MASK = "xxxx????";

        // Mob list iteration
        // Pattern: 48 8B 41 30 | mov rax, [rcx + 0x30]
        constexpr const char* MOB_LIST_NEXT = "\x48\x8B\x41\x30";
        constexpr const char* MOB_LIST_NEXT_MASK = "xxxx";

        // Player class/level read
        // Pattern: 8B 87 ?? ?? ?? ?? 89 C1 | mov eax, [rdi + offset]
        constexpr const char* PLAYER_CLASS = "\x8B\x87\x00\x00\x00\x00\x89\xC1";
        constexpr const char* PLAYER_CLASS_MASK = "xx????xx";
    }
}

