/**
 * Pathfinding and Route Management for MF Runs
 */

struct Waypoint
{
    float x, y;
    const char* name;
    int type;  // 0 = normal, 1 = teleport, 2 = interact (portal, chest)

    float Distance(const Waypoint& other) const
    {
        float dx = x - other.x;
        float dy = y - other.y;
        return sqrtf(dx * dx + dy * dy);
    }
};

struct Route
{
    const char* name;
    const char* area;
    std::vector<Waypoint> waypoints;
    int expectedRuntime;  // in milliseconds
};

class PathFinding
{
public:
    PathFinding();
    ~PathFinding();

    // Load predefined routes
    const Route* GetRoute(const char* routeName) const;

    // Generate next waypoint based on current position and target
    Vector2D GetNextWaypoint(const Vector2D& currentPos, const Waypoint& target) const;

    // Find optimal path avoiding mobs
    std::vector<Vector2D> FindPath(const Vector2D& start, const Vector2D& end, 
                                    const std::vector<MobInfo>& obstacles) const;

    // Calculate distance between two points
    static float Distance(const Vector2D& a, const Vector2D& b)
    {
        float dx = a.x - b.x;
        float dy = a.y - b.y;
        return sqrtf(dx * dx + dy * dy);
    }

private:
    std::vector<Route> m_routes;

    void InitializeRoutes();

    // A* pathfinding implementation
    struct PathNode
    {
        Vector2D position;
        float gCost;  // Cost from start
        float hCost;  // Heuristic cost to goal
        PathNode* parent;

        float GetFCost() const { return gCost + hCost; }
    };

    bool IsWalkable(const Vector2D& pos, const std::vector<MobInfo>& obstacles) const;
};

