#include <algorithm>

PathFinding::PathFinding()
{
    InitializeRoutes();
}

PathFinding::~PathFinding()
{
}

void PathFinding::InitializeRoutes()
{
    m_routes.push_back(Routes::CowLevel);
    m_routes.push_back(Routes::ThePit);
    m_routes.push_back(Routes::AncientTunnels);
    m_routes.push_back(Routes::ChaosSanctuary);
    m_routes.push_back(Routes::BaalRun);
}

const Route* PathFinding::GetRoute(const char* routeName) const
{
    for (const auto& route : m_routes)
    {
        if (strcmp(route.name, routeName) == 0)
        {
            return &route;
        }
    }
    return nullptr;
}

Vector2D PathFinding::GetNextWaypoint(const Vector2D& currentPos, const Waypoint& target) const
{
    // Calculate direction to target
    float dx = target.x - currentPos.x;
    float dy = target.y - currentPos.y;
    float distance = sqrtf(dx * dx + dy * dy);

    if (distance == 0.0f)
        return currentPos;

    // Normalize and scale to movement step
    const float STEP_SIZE = 10.0f;
    float step = std::min(STEP_SIZE, distance);

    Vector2D nextPos;
    nextPos.x = currentPos.x + (dx / distance) * step;
    nextPos.y = currentPos.y + (dy / distance) * step;

    return nextPos;
}

bool PathFinding::IsWalkable(const Vector2D& pos, const std::vector<MobInfo>& obstacles) const
{
    const float MOB_AVOIDANCE_RADIUS = 50.0f;

    for (const auto& mob : obstacles)
    {
        if (!mob.isAlive)
            continue;

        float dx = pos.x - mob.position.x;
        float dy = pos.y - mob.position.y;
        float distance = sqrtf(dx * dx + dy * dy);

        if (distance < MOB_AVOIDANCE_RADIUS)
            return false;
    }

    return true;
}

std::vector<Vector2D> PathFinding::FindPath(const Vector2D& start, const Vector2D& end,
                                            const std::vector<MobInfo>& obstacles) const
{
    std::vector<Vector2D> path;
    path.push_back(start);

    // Simple pathfinding: move towards target with mob avoidance
    const float GRID_SIZE = 20.0f;
    const float GRID_CHECK = 30.0f;

    Vector2D current = start;

    while (Distance(current, end) > GRID_SIZE)
    {
        // Calculate direction to target
        float dx = end.x - current.x;
        float dy = end.y - current.y;
        float distance = sqrtf(dx * dx + dy * dy);

        if (distance == 0.0f)
            break;

        // Normalize
        float ndx = dx / distance;
        float ndy = dy / distance;

        // Check if we can move directly
        Vector2D directNext;
        directNext.x = current.x + ndx * GRID_CHECK;
        directNext.y = current.y + ndy * GRID_CHECK;

        if (IsWalkable(directNext, obstacles))
        {
            current = directNext;
            path.push_back(current);
        }
        else
        {
            // Try perpendicular directions (mob avoidance)
            Vector2D leftNext;
            leftNext.x = current.x + (-ndy) * GRID_CHECK;
            leftNext.y = current.y + ndx * GRID_CHECK;

            Vector2D rightNext;
            rightNext.x = current.x + ndy * GRID_CHECK;
            rightNext.y = current.y + (-ndx) * GRID_CHECK;

            if (IsWalkable(leftNext, obstacles))
            {
                current = leftNext;
                path.push_back(current);
            }
            else if (IsWalkable(rightNext, obstacles))
            {
                current = rightNext;
                path.push_back(current);
            }
            else
            {
                // Back off and try again
                current.x -= ndx * GRID_SIZE;
                current.y -= ndy * GRID_SIZE;
            }
        }

        // Safety check to prevent infinite loops
        if (path.size() > 500)
            break;
    }

    path.push_back(end);
    return path;
}

