uintptr_t MemoryReader::FindPattern(const char* pattern, const char* mask, uintptr_t startAddress, size_t searchSize) const
{
    if (!m_processHandle)
        return 0;

    size_t patternLength = strlen(mask);
    if (patternLength == 0 || searchSize < patternLength)
        return 0;

    std::unique_ptr<unsigned char[]> buffer(new unsigned char[searchSize]);

    if (!ReadProcessMemory(m_processHandle, (LPCVOID)startAddress, buffer.get(), searchSize, nullptr))
        return 0;

    for (size_t i = 0; i <= searchSize - patternLength; i++)
    {
        bool match = true;
        for (size_t j = 0; j < patternLength; j++)
        {
            // 'x' = must match, '?' = wildcard (any byte)
            if (mask[j] == 'x' && buffer[i + j] != (unsigned char)pattern[j])
            {
                match = false;
                break;
            }
        }

        if (match)
            return startAddress + i;
    }

    return 0;
}

uintptr_t MemoryReader::FindPatternEx(const unsigned char* pattern, const char* mask, uintptr_t startAddress, size_t searchSize) const
{
    if (!m_processHandle)
        return 0;

    size_t patternLength = strlen(mask);
    if (patternLength == 0 || searchSize < patternLength)
        return 0;

    std::unique_ptr<unsigned char[]> buffer(new unsigned char[searchSize]);

    if (!ReadProcessMemory(m_processHandle, (LPCVOID)startAddress, buffer.get(), searchSize, nullptr))
        return 0;

    for (size_t i = 0; i <= searchSize - patternLength; i++)
    {
        bool match = true;
        for (size_t j = 0; j < patternLength; j++)
        {
            if (mask[j] == 'x' && buffer[i + j] != pattern[j])
            {
                match = false;
                break;
            }
        }

        if (match)
            return startAddress + i;
    }

    return 0;
}

uintptr_t MemoryReader::FindPatternRegion(const char* pattern, const char* mask, const MEMORY_BASIC_INFORMATION& region) const
{
    if (!m_processHandle || region.AllocationBase == nullptr)
        return 0;

    return FindPattern(pattern, mask, (uintptr_t)region.BaseAddress, region.RegionSize);
}

