#pragma once
#include <windows.h>
#include <cstdint>

class MemoryReader
{
public:
    MemoryReader(HANDLE processHandle);
    ~MemoryReader();

    template<typename T>
    T Read(uintptr_t address) const
    {
        T buffer = {};
        if (address == 0)
            return buffer;
        ReadProcessMemory(m_processHandle, (LPCVOID)address, &buffer, sizeof(T), nullptr);
        return buffer;
    }

    template<typename T>
    bool Write(uintptr_t address, const T& value) const
    {
        if (address == 0)
            return false;
        return WriteProcessMemory(m_processHandle, (LPVOID)address, (LPCVOID)&value, sizeof(T), nullptr);
    }

    /**
     * Find byte pattern in process memory
     * @param pattern Byte pattern to search (can be NULL bytes)
     * @param mask    Mask string: 'x' = must match, '?' = wildcard
     * @param startAddress Base address to search from
     * @param searchSize   Number of bytes to search
     * @return Address of pattern or 0 if not found
     */
    uintptr_t FindPattern(const char* pattern, const char* mask, uintptr_t startAddress, size_t searchSize) const;

    /**
     * Find pattern using unsigned char array
     */
    uintptr_t FindPatternEx(const unsigned char* pattern, const char* mask, uintptr_t startAddress, size_t searchSize) const;

    /**
     * Find pattern in specific memory region
     */
    uintptr_t FindPatternRegion(const char* pattern, const char* mask, const MEMORY_BASIC_INFORMATION& region) const;

    /**
     * Read null-terminated string
     */
    std::string ReadString(uintptr_t address, size_t maxLength = 256) const
    {
        std::string result;
        if (address == 0)
            return result;

        char buffer[256];
        size_t toRead = std::min(maxLength, sizeof(buffer) - 1);
        ReadProcessMemory(m_processHandle, (LPCVOID)address, buffer, toRead, nullptr);
        buffer[toRead] = '\0';
        result = buffer;
        return result;
    }

private:
    HANDLE m_processHandle;
};

