        return nullptr;

    // Find unallocated space first (stealth allocation)
    void* targetAddress = FindUnallocatedSpace(size);

    // Allocate at the unallocated space
    void* allocated = VirtualAllocEx(
        m_processHandle,
        targetAddress,
        size,
        MEM_COMMIT | MEM_RESERVE,
        PAGE_EXECUTE_READWRITE
    );

    if (allocated)
    {
        m_allocatedBlocks.push_back(allocated);
    }

    return allocated;
}

