void ProcessInjector::AddTimingJitter(int minMs, int maxMs) const
{
    // Add random delay to execution timing
    // Helps avoid automated detection of consistent timing patterns
    std::uniform_int_distribution<> dist(minMs, maxMs);
    int delayMs = dist(const_cast<std::mt19937&>(m_randomGen));
    std::this_thread::sleep_for(std::chrono::milliseconds(delayMs));
}

void* ProcessInjector::FindUnallocatedSpace(size_t size)
{
    if (!m_processHandle)
        return nullptr;

    MEMORY_BASIC_INFORMATION mbi = {};
    uintptr_t address = 0x10000; // Start above kernel space

    while (address < 0x7FFFFFFFFFF)
    {
        if (VirtualQueryEx(m_processHandle, (LPVOID)address, &mbi, sizeof(mbi)) == 0)
            break;

        // Look for free pages with sufficient size
        if (mbi.State == MEM_FREE && mbi.RegionSize >= size)
        {
            return (void*)address;
        }

        address += mbi.RegionSize;
    }

    return nullptr;
}

void* ProcessInjector::FindStealthfulSpace(size_t size)
{
    if (!m_processHandle)
        return nullptr;

    MEMORY_BASIC_INFORMATION mbi = {};
    uintptr_t address = 0x140000000; // Start in high memory (away from game module)
    std::vector<uintptr_t> candidates;

    // Scan for suitable regions
    while (address < 0x7FFFFFFFFFF && candidates.size() < 10)
    {
        if (VirtualQueryEx(m_processHandle, (LPVOID)address, &mbi, sizeof(mbi)) == 0)
            break;

        if (mbi.State == MEM_FREE && mbi.RegionSize >= size)
        {
            // Prefer regions not adjacent to allocated memory
            candidates.push_back(address);
        }

        address += mbi.RegionSize;
    }

    // Return a random candidate for maximum stealth
    if (!candidates.empty())
    {
        std::uniform_int_distribution<> dist(0, candidates.size() - 1);
        int idx = dist(m_randomGen);
        return (void*)candidates[idx];
    }

    return nullptr;
}

void* ProcessInjector::AllocateStealthMemory(size_t size)
{
    if (!m_processHandle)
        return nullptr;

    // Add random delay before allocation
    AddTimingJitter(10, 50);

    // Try stealthful allocation first (high memory regions)
    void* targetAddress = FindStealthfulSpace(size);

    // Fall back to regular unallocated space if needed
    if (!targetAddress)
