}

bool ProcessInjector::WriteToStealthMemory(void* address, const void* data, size_t size)
{
    if (!m_processHandle || !address || !data)
        return false;

    // Add random delay before write
    AddTimingJitter(5, 20);

    return WriteProcessMemory(m_processHandle, address, data, size, nullptr);
}

bool ProcessInjector::ExecuteStealthCode(void* codeAddress)
{
    if (!m_processHandle || !codeAddress)
        return false;

    // Create a remote thread to execute code at the allocated address
    HANDLE hThread = CreateRemoteThread(
        m_processHandle,
        nullptr,
        0,
        (LPTHREAD_START_ROUTINE)codeAddress,
        nullptr,
        0,
        nullptr
    );

    if (!hThread)
        return false;

    WaitForSingleObject(hThread, INFINITE);
    CloseHandle(hThread);
    return true;
}

bool ProcessInjector::ExecuteWithJitter(void* codeAddress, int minDelayMs, int maxDelayMs)
{
    if (!m_processHandle || !codeAddress)
        return false;

    // Add random delay before execution (anti-detection)
    AddTimingJitter(minDelayMs, maxDelayMs);

    return ExecuteStealthCode(codeAddress);
}

bool ProcessInjector::FreeAllAllocations()
{
    if (!m_processHandle)
        return false;

    bool allFreed = true;
    for (auto block : m_allocatedBlocks)
    {
        if (!VirtualFreeEx(m_processHandle, block, 0, MEM_RELEASE))
        {
            allFreed = false;
        }
    }

    m_allocatedBlocks.clear();
    return allFreed;
}

