#pragma once
#include <windows.h>
#include <cstdint>
#include <string>
#include <vector>

/**
 * Anti-Detection System
 * 
 * Spoof D2R process to appear as legitimate system process (Notepad/Calculator)
 * Techniques:
 * - Window title/class name spoofing
 * - Process name/module path redirection
 * - Memory pattern obfuscation
 * - API call hooking
 * - Registry hiding
 */

class AntiDetection
{
public:
    enum class SpoofTarget
    {
        NOTEPAD,      // Appear as Notepad.exe
        CALCULATOR,   // Appear as Calc.exe
        MSPAINT,      // Appear as mspaint.exe
        NONE          // No spoofing
    };

    AntiDetection(HANDLE gameProcessHandle);
    ~AntiDetection();

    /**
     * Apply spoofing to target process
     * @param target Which system process to spoof as
     * @return Success status
     */
    bool ApplySpoofing(SpoofTarget target);

    /**
     * Hook Windows API functions to intercept detection attempts
     * Hooks: GetModuleFileNameA/W, GetWindowTextA/W, QueryPerformanceCounter, etc.
     */
    bool HookDetectionAPIs();

    /**
     * Hide bot DLL from module enumeration
     * Makes it invisible to GetModuleHandle, EnumProcessModules, etc.
     */
    bool HideBotModule();

    /**
     * Randomize window class and title to avoid signature detection
     */
    bool RandomizeWindow();

    /**
     * Disable common anti-cheat detection methods
     */
    bool DisableDetectionHooks();

    /**
     * Unhook and restore original behavior
     */
    bool RemoveSpoofing();

    /**
     * Check if spoofing is currently active
     */
    bool IsSpoofingActive() const { return m_spoofingActive; }

    /**
     * Get current spoof target
     */
    SpoofTarget GetSpoofTarget() const { return m_currentTarget; }

private:
    HANDLE m_gameProcessHandle;
    DWORD m_gameProcessId;
    bool m_spoofingActive;
    SpoofTarget m_currentTarget;

    // Backup original values
    std::string m_originalWindowTitle;
    std::string m_originalModulePath;
    std::string m_originalWindowClass;

    // Hook-related data
    std::vector<void*> m_hookAddresses;
    std::vector<unsigned char*> m_originalBytes;

    // Spoof data
    struct SpoofData
    {
        const char* processName;
        const char* windowTitle;
        const char* windowClass;
        const char* modulePath;
    };

    static const SpoofData SPOOF_TARGETS[];

    bool SpoofWindowTitle(const char* newTitle);
    bool SpoofModulePath(const char* newPath);
    bool SpoofWindowClass(const char* newClass);

    /**
     * Inject hook stub into target process
     * Redirects API calls to custom handlers
     */
    bool InjectAPIHook(const char* apiName, uintptr_t hookAddress);

    /**
     * Generic hooking function that patches module IAT
     */
    bool HookIAT(const std::string& moduleName, const std::string& funcName, void* newFunc);

    /**
     * Detour function replacement in memory
     */
    bool DetourFunction(uintptr_t targetAddress, uintptr_t detourAddress, size_t minInstructionSize);
};

/**
 * Hook stub functions to be injected into target process
 * These will be called instead of real API functions
 */
namespace HookStubs
{
    // Hooks for GetModuleFileNameA/W
    extern "C" DWORD __stdcall GetModuleFileNameA_Hook(HMODULE hModule, LPSTR lpFilename, DWORD nSize);
    extern "C" DWORD __stdcall GetModuleFileNameW_Hook(HMODULE hModule, LPWSTR lpFilename, DWORD nSize);

    // Hooks for GetWindowText
    extern "C" int __stdcall GetWindowTextA_Hook(HWND hWnd, LPSTR lpString, int nMaxCount);
    extern "C" int __stdcall GetWindowTextW_Hook(HWND hWnd, LPWSTR lpString, int nMaxCount);

    // Hooks for QueryPerformanceCounter (detects automation patterns)
    extern "C" BOOL __stdcall QueryPerformanceCounter_Hook(LARGE_INTEGER* lpPerformanceCount);

    // Hooks for GetTickCount (detects consistent timing)
    extern "C" DWORD __stdcall GetTickCount_Hook();
}

