#include <string>
#include "AntiDetection.h"

/**
 * Bot Configuration and Initialization
 * 
 * Controls all bot behavior including:
 * - Anti-detection settings
 * - Route selection
 * - Behavior randomization
 * - Safety parameters
 */

struct BotConfig
{
    // Anti-Detection Settings
    bool enableAntiDetection = true;
    AntiDetection::SpoofTarget spoofTarget = AntiDetection::SpoofTarget::NOTEPAD;
    bool hideModules = true;
    bool randomizeWindowTitle = true;
    bool addTimingJitter = true;
    int minInputDelayMs = 50;
    int maxInputDelayMs = 200;

    // Route Settings
    std::string selectedRoute = "Cow Level";
    bool teleportPreload = true;
    bool autoPickup = true;
    float pickupRadius = 50.0f;

    // Behavioral Settings
    bool randomizePathfinding = true;
    bool simulateHumanMovement = true;
    int randomMovementJitterMs = 100;
    float randomDirectionVariance = 0.15f; // 15% deviation from straight path

    // Safety Settings
    bool pauseOnDetection = true;
    bool logSuspiciousActivity = true;
    int maxConsecutiveRunsBeforePause = 10;
    int pauseDurationMs = 5000;

    // Performance Settings
    int gameStateRefreshRateMs = 100;
    int mobDetectionRadiusMeters = 200;
    int maxMobsToTrack = 50;

    // Debug Settings
    bool verboseLogging = false;
    bool enableMemoryLogging = false;
    std::string logFilePath = "D2RBot.log";
};

/**
 * Builder pattern for easier configuration
 */
class BotConfigBuilder
{
private:
    BotConfig m_config;

public:
    BotConfigBuilder() = default;

    BotConfigBuilder& WithAntiDetection(bool enabled)
    {
        m_config.enableAntiDetection = enabled;
        return *this;
    }

    BotConfigBuilder& WithSpoofTarget(AntiDetection::SpoofTarget target)
    {
        m_config.spoofTarget = target;
        return *this;
    }

    BotConfigBuilder& WithRoute(const std::string& routeName)
    {
        m_config.selectedRoute = routeName;
        return *this;
    }

    BotConfigBuilder& WithTeleportPreload(bool enabled)
    {
        m_config.teleportPreload = enabled;
        return *this;
    }

    BotConfigBuilder& WithAutoPickup(bool enabled)
    {
        m_config.autoPickup = enabled;
        return *this;
    }

    BotConfigBuilder& WithInputJitter(int minMs, int maxMs)
    {
        m_config.minInputDelayMs = minMs;
        m_config.maxInputDelayMs = maxMs;
        return *this;
    }

    BotConfigBuilder& WithLogging(bool verbose, const std::string& filePath)
    {
        m_config.verboseLogging = verbose;
        m_config.logFilePath = filePath;
        return *this;
    }

    const BotConfig& Build() const
    {
        return m_config;
    }
};

// Preset configurations
namespace BotPresets
{
    // Maximum stealth - prioritizes anti-detection
    inline BotConfig StealthMode()
    {
        return BotConfigBuilder()
            .WithAntiDetection(true)
            .WithSpoofTarget(AntiDetection::SpoofTarget::NOTEPAD)
            .WithInputJitter(100, 300)
            .Build();
    }

    // Balanced - reasonable speed with moderate anti-detection
    inline BotConfig BalancedMode()
    {
        return BotConfigBuilder()
            .WithAntiDetection(true)
            .WithSpoofTarget(AntiDetection::SpoofTarget::CALCULATOR)
            .WithInputJitter(50, 150)
            .Build();
    }

    // Performance mode - minimal anti-detection, maximum speed
    inline BotConfig PerformanceMode()
    {
        return BotConfigBuilder()
            .WithAntiDetection(false)
            .WithInputJitter(10, 50)
            .Build();
    }

    // Cow Level Runner
    inline BotConfig CowLevelRunner()
    {
        return BotConfigBuilder()
            .WithRoute("Cow Level")
            .WithAutoPickup(true)
            .WithTeleportPreload(false)
            .WithAntiDetection(true)
            .WithInputJitter(75, 200)
            .Build();
    }

    // Chaos Sanctuary Runner (geared character)
    inline BotConfig ChaosRunner()
    {
        return BotConfigBuilder()
            .WithRoute("Chaos Sanctuary")
            .WithAutoPickup(true)
            .WithTeleportPreload(true)
            .WithAntiDetection(true)
            .WithInputJitter(50, 150)
            .Build();
    }

    // Baal Runner (endgame farming)
    inline BotConfig BaalRunner()
    {
        return BotConfigBuilder()
            .WithRoute("Baal Run")
            .WithAutoPickup(true)
            .WithTeleportPreload(true)
            .WithAntiDetection(true)
            .WithInputJitter(60, 180)
            .Build();
    }
}

